/** API presentation uses the existing visual system; all prices and checkout come from the server. */
import {ApiTripController,visibleText} from './api-model.js';
import {formatAssistantText} from './message-format.js';
import {adultsLabel,nightsLabel,optionsLabel,formatDate,formatRating,refundLabel,transferLabel,priceRows,tripAssumptions,narrativeView,isoDay,isTrainTrip,trainPresentation,demoDepartureDate} from './trip-presentation.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>Number.isFinite(value)?value.toLocaleString('ru-RU')+' ₽':'неизвестно';
const names={MOW:'Москва',SVO:'Москва · Шереметьево',LED:'Санкт-Петербург',AYT:'Анталья',DXB:'Дубай',MLE:'Мальдивы'};
const place=code=>names[code]||code||'Пока не выбрано';
const day=formatDate;
const localTime=value=>typeof value==='string'&&isoDay(value)&&value.length>=16?day(value)+' · '+value.slice(11,16)+' (UTC'+(value.endsWith('Z')?'+0':value.slice(-6))+')':'время не уточнено';
const extras=items=>(items||[]).map(value=>({return_transfer:'трансфер обратно в аэропорт',visa_and_other_required_extras:'визы и прочие обязательные доплаты',arrival_transfer:'трансфер в отель'}[value]||'дополнительные услуги')).join(', ');
const sourceLabel=leg=>leg?.demo_source?.kind==='deterministic_mock'?'<span class="api-source mock">ДЕМО-МОК · расписание и цена сгенерированы</span>':leg?.price_source?'<span class="api-source provider">Aviasales · сохранённая котировка</span>':'<span class="api-source mock">Расчётные демо-данные</span>';
const disclaimer='Демо без списаний. Билеты не выписываются, отель и трансферы не бронируются. Наличие мест и цена покупки не подтверждены.';
const imageFor=index=>['hotel-pool','room-warm','room-light'][index%3];

export function mountApiApp({root,modal,icon,config}){
 let connection='connecting',statusText='',modalOpener=null,paymentBusy=false,recoveryTimer=null,recoveryDelay=2000,disposed=false;
 let compared=new Set(),comparisonKey='',compareNotice='',modalSearchKey=null,modalNeedsFresh=false;
 const openDisclosures=new Set();
 const toast=message=>{const element=document.getElementById('toast');element.textContent=visibleText(message);element.classList.add('show');setTimeout(()=>element.classList.remove('show'),4000);};
 let tabStorage=null;try{tabStorage=globalThis.sessionStorage;}catch{}
 const controller=new ApiTripController({onChange:()=>{render();scheduleRecovery();},storage:tabStorage});
 const current=()=>controller.state;
 const actionsBlocked=()=>current().busy||!!current().pendingRequest||current().syncNeeded||current().sessionLost;
 const selected=()=>current().options.find(option=>option.index===current().selected)||current().options[0];
 const searchReady=()=>!current().stale&&!current().sessionLost&&current().stage!=='collecting';
 const searchKey=()=>JSON.stringify([current().sessionId,current().brief,current().optionKind,current().options]);
 const disclosure=key=>openDisclosures.has(key)?' open':'';
 const button=(action,text,index=null,primary=false)=>`<button class="action-button ${primary?'primary':''}" data-api-action="${action}" ${index===null?'':`data-index="${index}"`} ${actionsBlocked()?'disabled':''}>${text}</button>`;
 function close(){if(modal.open)modal.close();modalSearchKey=null;modalOpener?.isConnected&&modalOpener.focus({preventScroll:true});}
 function open(title,body,footer='',searchModal=false){
  if(!modal.open)modalOpener=document.activeElement;
  modalSearchKey=searchModal?searchKey():null;
  modalNeedsFresh=searchModal===true;
  modal.innerHTML=`<div class="modal-head"><h2 id="api-modal-title">${esc(title)}</h2><button class="close-modal" data-api-action="close" aria-label="Закрыть окно">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;
  modal.setAttribute('aria-labelledby','api-modal-title');if(!modal.open)modal.showModal();modal.scrollTop=0;
 }
 function welcome(){const date=demoDepartureDate();return `<section class="welcome"><div class="eyebrow">ОДИН ДИАЛОГ — ВЕСЬ ПЛАН</div><div class="hero-top"><div><h1>Куда хочется<br>прямо сейчас?</h1><p class="hero-copy">Соберём перелёты, отель и трансфер. Расскажите о поездке — учтём даты, бюджет и важные детали.</p></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="art-card">${icon('plane')}</div><div class="orbit"></div></div></div><div class="quick-prompts">${[['Анталью','Солнце и море'],['Дубай','Город и пляж'],['Мале','На Мальдивы']].map(([name,label])=>`<button class="prompt" data-api-prompt="${esc(`Из Москвы в ${name} ${day(date)} на неделю вдвоём`)}"><span class="prompt-icon">${icon('sun')}</span><div><b>${label}</b><small>${day(date)} · 7 ночей · двое</small></div></button>`).join('')}</div><p class="welcome-note">Сохранённые котировки отмечены Aviasales. Сгенерированные рейсы явно подписаны «ДЕМО-МОК». Проживание и трансферы — расчётные.</p></section>`;}
 function flight(leg,title){if(!leg)return `<div class="api-flight"><b>${esc(title)}</b><span>Перелёт не оценён</span></div>`;return `<div class="api-flight"><b>${esc(title)} · ${esc(place(leg.from))} → ${esc(place(leg.to))}</b>${sourceLabel(leg)}<small>${esc(localTime(leg.departure_at))} → ${esc(localTime(leg.arrival_at))}</small><span>${money(leg.price_rub)} за группу + ${money(leg.baggage_price_rub)} багаж</span>${leg.price_source?`<small>За место: ${money(leg.price_source.seat_price_rub)} · снимок ${day(leg.price_source.recorded_at)}. Наличие не подтверждено.</small>`:'<small>Это учебное расписание и расчётная цена, не котировка поставщика.</small>'}</div>`;}
 function issues(option){return Array.isArray(option.issues)&&option.issues.length?`<div class="risk-note">${option.issues.map(issue=>`<p>${issue.severity==='critical'?'Требует исправления: ':''}${esc(visibleText(issue.message))}</p>`).join('')}</div>`:'';}
 function unknownExtras(option){return extras(option.unpriced_components)||'прочие обязательные доплаты: состав и стоимость не уточнены';}
 function parts(option){return `<div class="plan-inline"><div class="plan-line">${icon('building')}<div><b>${esc(option.hotel.name)}</b><small>${day(option.hotel.check_in)} — ${day(option.hotel.check_out)} · ${nightsLabel(option.hotel.nights)}</small></div><b>${money(option.hotel.price_rub)}</b></div>${flight(option.outbound,'Туда')}${flight(option.inbound,'Обратно')}<div class="plan-line">${icon('car')}<div><b>${esc(transferLabel(option.transfer))}</b><small>Обратный трансфер не оценён</small></div><b>${money(option.transfer?.price_rub)}</b></div><div class="plan-sum"><span>Известная часть стоимости за всех</span><strong>${money(option.known_total_rub)}</strong></div></div><p class="risk-note">Не оценены: ${esc(unknownExtras(option))}. Полная стоимость поездки не подтверждена.</p>${issues(option)}`;}
 function priceBreakdown(option){const key=`price-${option.index}`;return `<details class="api-price-breakdown" data-disclosure="${key}"${disclosure(key)}><summary>Из чего складывается сумма</summary><dl>${priceRows(option).map(row=>`<div><dt>${esc(row.label)}</dt><dd>${money(row.value)}</dd></div>`).join('')}<div class="api-price-known"><dt>Известная часть за всю группу</dt><dd>${money(option.known_total_rub)}</dd></div></dl><p>Не оценены: ${esc(unknownExtras(option))}. Показанная сумма не является полной ценой поездки.</p></details>`;}
 function assumptions(){
  const state=current();if(!searchReady()||!state.options.length)return '';
  const rows=tripAssumptions(searchReady()?state:{...state,options:[],assumptions:[]});if(!rows.length)return '';
  return `<section class="api-assumptions" aria-label="Предположения для расчёта"><h2>${state.assumptionsAccepted?'Предположения проверены':'Проверьте предположения'}</h2><p>${state.assumptionsAccepted?'Вы приняли эти условия для поиска. При новом подборе проверка сбросится.':'Эти условия ещё не были названы вами прямо. Их можно принять для поиска или изменить.'}</p><ul>${rows.map(row=>`<li><div><strong>${esc(row.label)}: ${esc(row.display)}</strong><span class="api-assumption-source">${row.source==='default'?'По умолчанию':'Предложено агентом'}</span></div>${row.explanation?`<small>${esc(visibleText(row.explanation))}</small>`:''}</li>`).join('')}</ul><div class="action-row"><button class="action-button primary" data-api-action="accept-assumptions" ${actionsBlocked()||state.assumptionsAccepted?'disabled':''}>${state.assumptionsAccepted?'Предположения проверены':'Подходит для поиска'}</button>${button('edit-preferences','Изменить условия')}</div><small>Проверка предположений не выбирает вариант и не начинает оформление.</small></section>`;
 }
 function assistantMessage(message,index){
  const view=narrativeView(visibleText(message.text));
  if(!view.compact||message.interrupted||message.error||(current().busy&&index===current().messages.length-1))return `<div class="assistant-text">${formatAssistantText(view.text)}</div>`;
  const key=`message-${index}`;
  return `<div class="assistant-text api-message-overview">${formatAssistantText(view.preview)}</div>${view.warnings.length?`<div class="api-visible-warnings" aria-label="Оговорки полного ответа">${view.warnings.map(text=>`<div class="assistant-text">${formatAssistantText(text)}</div>`).join('')}<button class="api-full-answer-link" data-api-action="expand-message" data-message-index="${index}" aria-controls="api-full-answer-${index}">Все оговорки и условия по вариантам</button></div>`:''}<details id="api-full-answer-${index}" class="api-message-details" data-disclosure="${key}"${disclosure(key)}><summary>Подробнее — весь ответ</summary><div class="assistant-text">${formatAssistantText(view.text)}</div></details>`;
 }
 function comparison(){
  const options=current().options.filter(option=>compared.has(option.index));if(options.length<2)return '';
  const rows=[['Известная часть за группу',option=>money(option.known_total_rub)],['Рейтинг отеля',option=>formatRating(option.hotel.rating)+' / 10'],['Возврат отеля',option=>refundLabel(option.hotel.refundable)],['Трансфер в отель',option=>transferLabel(option.transfer)+(Number.isFinite(option.transfer?.price_rub)?' · '+money(option.transfer.price_rub):' · цена не оценена')]];
  return `<section class="api-comparison" aria-label="Сравнение вариантов"><div class="api-comparison-title"><h2>Сравнение вариантов</h2><button class="action-button" data-api-action="clear-comparison">Очистить сравнение</button></div><div class="api-comparison-scroll" tabindex="0" role="region" aria-label="Таблица сравнения: можно прокрутить по горизонтали"><table><caption>Только текущие предложения; все суммы за показанные компоненты.</caption><thead><tr><th scope="col">Условие</th>${options.map(option=>`<th scope="col">Вариант ${option.index}<br>${esc(option.hotel.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th>${options.map(option=>`<td>${esc(value(option))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="demo-data-note">Полная стоимость не подтверждена: обратный трансфер, визы и прочие обязательные доплаты не оценены. Сравнение не выбирает поездку.</p></section>`;
 }
 function cards(){
  const state=current();
  if(state.sessionLost)return '';
  if(state.stage==='collecting'&&!state.stale&&!state.sessionLost&&!state.options.length&&state.notes.length)return `<div class="empty-result"><strong>Подтверждённых вариантов пока нет.</strong><p>${esc(visibleText(state.notes.join(' ')))}</p><p>Измените даты или условия в чате, чтобы повторить поиск.</p></div>`;
  if(!searchReady())return state.messages.length&&Object.keys(state.brief).length?`<section class="api-search-update" role="status"><strong>${state.busy?'Обновляем подбор':'Уточняем условия поездки'}</strong><p>Предыдущие предложения больше не показываются как актуальные. ${state.busy?'Новые варианты появятся после ответа.':'Ответьте в чате или измените условия, чтобы продолжить поиск.'}</p></section>`:'';
  if(state.optionKind==='packages'){
   if(!state.options.length)return `<div class="empty-result"><strong>Подтверждённых вариантов пока нет.</strong><p>${esc(state.notes.join(' '))}</p><p>Измените даты или условия в чате. Подставлять неподтверждённые цены не будем.</p></div>`;
   return `<section class="api-results"><div class="search-caption"><span>${optionsLabel(state.options.length)} с сервера · ${adultsLabel(state.brief.adults??state.options[0]?.travelers?.adults)}</span><span>Можно сравнить 2–3 варианта</span></div><div class="hotel-grid">${state.options.map((option,index)=>`<article class="hotel-card ${state.selected===option.index?'selected-card':''}"><div class="hotel-photo"><img src="./assets/${imageFor(index)}.svg" alt="Иллюстрация отдыха, не фотография выбранного отеля"><span class="card-photo-label">Иллюстрация</span></div><div class="card-content"><div class="hotel-topline">Вариант ${option.index} · ${esc(place(option.destination))}</div><h3>${esc(option.hotel.name)}</h3><div class="api-hotel-rating">${Number.isInteger(option.hotel.stars)?option.hotel.stars+'★ · ':''}Рейтинг ${formatRating(option.hotel.rating)}${Number.isFinite(option.hotel.rating)?' / 10':''}</div><div class="hotel-location">${day(option.hotel.check_in)} — ${day(option.hotel.check_out)} · ${nightsLabel(option.hotel.nights)}</div><p class="api-refund">${refundLabel(option.hotel.refundable)}</p><div class="api-card-sources">Туда: ${sourceLabel(option.outbound)}<br>Обратно: ${sourceLabel(option.inbound)}</div><div class="price-amount">${money(option.known_total_rub)}</div><div class="price-total">Известная часть стоимости за всю группу. Прочие доплаты не оценены.</div>${priceBreakdown(option)}${option.issues?.length?issues(option):''}${Array.isArray(option.risks)&&option.risks.length?`<details class="api-card-risks" data-disclosure="risk-${option.index}"${disclosure('risk-'+option.index)}><summary>Риски и ограничения · ${option.risks.length}</summary><ul>${option.risks.map(risk=>`<li>${esc(visibleText(risk))}</li>`).join('')}</ul></details>`:''}<div class="action-row">${button('plan','Состав поездки',option.index)}<button class="action-button primary" data-api-action="choose" data-index="${option.index}" ${actionsBlocked()||option.can_confirm!==true?'disabled':''}>${state.selected===option.index?'Выбран':'Выбрать'}</button></div>${option.can_confirm!==true?'<p class="risk-note">Оформление недоступно: обязательные условия не подтверждены.</p>':''}<div class="action-row">${button('profile','Почему этот отель?',option.index)}<button class="action-button api-compare-toggle" data-api-action="compare" data-index="${option.index}" aria-pressed="${compared.has(option.index)}" ${actionsBlocked()?'disabled':''}>${compared.has(option.index)?'Убрать из сравнения':'Добавить к сравнению'}</button></div></div></article>`).join('')}</div>${compareNotice?`<p class="api-compare-notice" role="status">${esc(compareNotice)}</p>`:''}${comparison()}<div class="api-followups">${button('savings','Есть ли даты дешевле?')} ${state.stage==='awaiting_confirmation'?button('confirm','Подтверждаю состав',null,true):''}${state.cart&&!state.order?button('checkout','Продолжить оформление',null,true):''}</div><p class="demo-data-note">${esc(disclaimer)}</p></section>`;
  }
  if(state.optionKind==='destinations')return `<div class="direction-grid">${state.options.map(option=>`<article class="direction-card"><div class="direction-body"><h3>${esc(option.name)}</h3><p>${esc(option.why?.join(' · ')||'Параметры направления требуют уточнения')}</p><p>Справочная оценка: ${money(option.estimated_total_rub)}. Полная стоимость не подтверждена.</p><button class="action-button primary" data-api-prompt="${esc(`Хочу в ${option.name}`)}">Выбрать направление</button></div></article>`).join('')}</div>`;
  if(state.optionKind==='trains')return `<section class="api-trains" aria-label="Найденные поезда"><div class="search-caption"><span>${optionsLabel(state.options.length)} с сервера · ${adultsLabel(state.brief.adults)}</span><span>Поиск без оформления</span></div><div class="api-train-grid">${state.options.map(option=>{const view=trainPresentation(option);return `<article class="api-train-card"><div class="hotel-topline">${esc(place(option.origin?.iata))} → ${esc(place(option.destination?.iata))}</div><h3>Поезд № ${esc(view.number)}</h3><p class="api-train-class">${esc(view.seatClass)}</p><div class="api-train-stations"><div><span>Отправление</span><b>${esc(view.originStation)}</b><small>${esc(localTime(option.departure_at))}</small></div><div><span>Прибытие</span><b>${esc(view.destinationStation)}</b><small>${esc(localTime(option.arrival_at))}</small></div></div><div class="price-amount">${money(option.price_rub)}</div><p class="price-total">За всю группу в одну сторону · обратный билет не включён</p><span class="api-source mock">${esc(view.priceLabel)}</span><p class="api-train-limitation">${esc(view.limitation)}</p></article>`;}).join('')}</div><div class="api-followups">${button('edit-preferences','Изменить пассажиров или дату')}</div>${state.notes.length?`<p class="demo-data-note">${esc(visibleText(state.notes.join(' ')))}</p>`:''}</section>`;
  return '';
 }
 function evidence(){const state=current();if(!searchReady())return '';return `${state.profile?.status==='available'?`<details class="api-evidence"><summary>Почему подходит: факты из синтетических отзывов</summary><p>В группе: ${state.profile.segment_review_count} синтетических отзывов. Это демонстрационные примеры, а не настоящие отзывы гостей.</p>${state.profile.evidence.map(row=>`<blockquote>${row.sentiment==='negative'?'Риск':'Плюс'}: «${esc(row.quote)}»</blockquote>`).join('')}</details>`:''}${state.savings?`<div class="api-evidence"><b>Сравнение дат</b><p>${state.savings.comparison_status==='compared'?`Проверено сопоставимых дат: ${state.savings.checked_dates?.filter(row=>row.status==='quoted').length||0}.`:'Нет полного набора котировок — подтвердить экономию нельзя.'}</p>${state.savings.contains_mock?'<p class="api-source mock">Демо-оценка: часть сравниваемых рейсов — моки.</p>':''}${state.savings.suggestions?.map(saving=>`<p>${day(saving.suggested_departure)}: ${money(saving.suggested_total_rub)} · экономия ${money(saving.saving_rub)} по показанным компонентам.</p>`).join('')||'<p>Вариантов с подтверждённой экономией больше 5% не показано.</p>'}<small>Обратный трансфер, визы и прочие доплаты не оценены. Сравнение не меняет выбранную поездку.</small></div>`:''}`;}
 function sidebar(){
  const state=current(),brief=state.brief,rail=isTrainTrip(state),assumed=tripAssumptions(searchReady()?state:{...state,options:[],assumptions:[]});
  const value=field=>brief[field]??assumed.find(row=>row.field===field)?.value;
  const source=field=>{const kind=state.sources[field]||assumed.find(row=>row.field===field)?.source;return ['default','inferred'].includes(kind)?`<small class="api-side-source">${kind==='default'?'По умолчанию':'Предложено агентом'}</small>`:'';};
  return `<button class="drawer-close" data-api-action="close-filters" aria-label="Закрыть параметры">${icon('close')}</button><div class="sidebar-title"><h2>Ваша поездка</h2><span class="synced">${icon('refresh')}Из чата</span></div><div class="side-field"><div class="field-label">Маршрут</div><p class="side-known-value">${esc(place(brief.origin))} → ${esc(place(brief.destination))}</p></div><div class="side-field"><div class="field-label">${rail?'Дата отправления':'Когда'}</div><p class="side-known-value">${value('start_date')?day(value('start_date')):'Уточним в чате'}${source('start_date')}${!rail&&value('nights')?` · ${nightsLabel(value('nights'))}${source('nights')}`:''}</p></div><div class="side-field"><div class="field-label">Кто с нами</div><p class="side-known-value">${adultsLabel(value('adults'))}${source('adults')}${brief.children_ages?.length?` · дети: ${brief.children_ages.map(age=>esc(age)).join(', ')} лет`:''}${brief.pets?` · питомцев: ${esc(brief.pets)}`:''}</p></div>${brief.budget_rub?`<div class="side-field"><div class="field-label">Бюджет за всех</div><p class="side-known-value">${money(brief.budget_rub)}</p></div>`:''}${state.needs.length?`<div class="side-features">${state.needs.map(need=>`<span class="feature-chip on">${esc(need.label)}</span>`).join('')}</div>`:''}<p class="demo-data-note">Параметры меняются через чат. Все суммы пересчитывает сервер.</p>${Object.keys(brief).length?button('edit-preferences','Изменить условия'):''}${!rail&&searchReady()&&state.stage==='awaiting_confirmation'?`<button class="side-plan" data-api-action="confirm" ${actionsBlocked()?'disabled':''}>Подтвердить состав ${icon('arrow')}</button>`:''}${!rail&&searchReady()&&state.cart&&!state.order?`<button class="side-plan" data-api-action="checkout" ${actionsBlocked()?'disabled':''}>Продолжить оформление</button>`:''}${state.order?'<button class="side-plan" data-api-action="success">Демо-заказ и документы</button>':''}`;
 }
 function recovery(){
  const state=current();if(state.busy)return '';
  const button=(action,label)=>`<button class="action-button ${action==='retry'?'primary':''}" data-api-action="${action}">${label}</button>`;
  if(state.sessionLost)return `<section class="api-recovery" role="status"><strong>${state.order?'Демо-заказ сохранён':'Переписка сохранена'}</strong><p>${esc(state.order?'Поисковая сессия завершилась. Демо-заказ и документы доступны; для продолжения разговора начните новый поиск.':state.error||'Сервер больше не может восстановить этот ответ.')}</p><div class="action-row">${state.order?button('success','Открыть документы'):state.orders.length?button('orders','Сохранённые демо-поездки'):''}${button('restart-session','Начать новый поиск')}</div></section>`;
  if(state.pendingRequest)return `<section class="api-recovery" role="status"><strong>${state.connection==='online'?'Можно продолжить':'Восстанавливаем связь'}</strong><p>${esc(state.error||'Ответ прервался. Сообщения и полученная часть ответа сохранены.')}</p><div class="action-row">${button('retry','Повторить сообщение')}${button('reconnect','Проверить связь')}</div><small>Повтор получит тот же ответ, если сообщение уже обработано.</small></section>`;
  if(state.syncNeeded)return `<section class="api-recovery" role="status"><strong>Ответ сохранён</strong><p>Осталось обновить состояние поездки.</p>${button('reconnect','Восстановить связь')}</section>`;
  if(state.connection==='offline'||state.connection==='auth')return `<section class="api-recovery" role="status"><strong>${state.connection==='auth'?'Нужно войти в сайт':'Нет связи'}</strong><p>Переписка остаётся в этой вкладке. ${state.connection==='auth'?'Повторите вход с прежним паролем.':'Соединение проверяется автоматически.'}</p>${button('reconnect','Проверить связь')}</section>`;
  return '';
 }
 function scheduleRecovery(){
  const state=current(),needed=!disposed&&document.visibilityState!=='hidden'&&!state.busy&&!state.sessionLost&&(state.connection==='offline'||(state.syncNeeded&&state.connection!=='connecting'));
  if(!needed){clearTimeout(recoveryTimer);recoveryTimer=null;if(state.connection==='online')recoveryDelay=2000;return;}
  if(recoveryTimer)return;
  recoveryTimer=setTimeout(()=>{recoveryTimer=null;recoveryDelay=Math.min(30000,recoveryDelay*2);void controller.reconnect();},recoveryDelay);
 }
 function render(){
  const state=current(),input=root.querySelector('#api-chat-input'),area=root.querySelector('.chat-scroll'),active=document.activeElement;
  const key=searchKey();if(key!==comparisonKey||!searchReady()){compared.clear();compareNotice='';comparisonKey=key;}
  if(modal.open&&modalSearchKey!==null&&(modalSearchKey!==key||modalNeedsFresh&&(state.stale||state.sessionLost)))close();
  for(const item of root.querySelectorAll?.('details[data-disclosure]')||[]){if(item.open)openDisclosures.add(item.dataset.disclosure);else openDisclosures.delete(item.dataset.disclosure);}
  const draft=state.draft,focus=active===input,selection=input?[input.selectionStart,input.selectionEnd]:null;
  const top=area?.scrollTop||0,nearBottom=!area||area.scrollHeight-area.scrollTop-area.clientHeight<160,drawer=root.querySelector('.sidebar')?.classList.contains('open');
  connection=state.connection;
  const hasCriteria=Object.keys(state.brief).length>0;
  root.innerHTML=`<div class="app-shell api-mode ${hasCriteria?'has-criteria':'no-criteria'}"><header class="topbar"><button class="brand" data-api-action="new" aria-label="Новая поездка"><span class="brand-mark">${icon('arch')}</span>островок</button><div class="header-actions"><button class="text-icon" data-api-action="orders">${icon('bag')}<span>Мои поездки</span></button>${hasCriteria?`<button class="mobile-filters" data-api-action="filters">${icon('sliders')}Поездка</button>`:''}</div></header><nav class="rail" aria-label="Основная навигация"><button class="new-trip" data-api-action="new" aria-label="Новая поездка">${icon('plus')}</button><button class="active" data-api-action="home" aria-label="Чат">${icon('chat')}</button><button data-api-action="orders" aria-label="Мои поездки">${icon('bag')}</button><button class="rail-bottom" data-api-action="about" aria-label="Как работает демо">${icon('help')}</button></nav><main class="workspace"><div class="chat-scroll" aria-live="polite" aria-busy="${state.busy}"><div class="chat-stream">${state.messages.length?state.messages.map((message,index)=>`<div class="message ${message.role} ${message.error?'error':''}">${message.role==='user'?`<div class="user-bubble">${esc(message.text)}</div>`:`<div class="assistant-label"><span class="assistant-mini">${icon('arch')}</span>О!дин запрос</div>${assistantMessage(message,index)}${message.interrupted?'<small class="api-partial-label">Ответ получен не полностью</small>':''}`}</div>`).join(''):welcome()}${state.busy?`<div class="typing-pill" role="status">${icon('refresh')}${esc(state.statusText||'Готовим ответ')}</div>`:''}${state.question?.quick_replies?.length?`<div class="action-row">${state.question.quick_replies.map(reply=>`<button class="action-button" data-api-prompt="${esc(reply)}" ${actionsBlocked()?'disabled':''}>${esc(reply)}</button>`).join('')}</div>`:''}${recovery()}${assumptions()}${cards()}${evidence()}${state.storageWarning?`<p class="api-error" role="alert">${esc(state.storageWarning)}</p>`:''}${state.error&&!state.pendingRequest&&!state.syncNeeded&&!state.sessionLost?`<p class="api-error" role="alert">${esc(state.error)}</p>`:''}</div></div><footer class="composer-wrap"><form id="api-chat-form" class="input-box"><textarea id="api-chat-input" aria-label="Расскажите о поездке" placeholder="Расскажите, куда хочется…" rows="1" maxlength="4000"></textarea><button class="send-button" type="${state.busy?'button':'submit'}" ${state.busy?'data-api-action="stop"':''} aria-label="${state.busy?'Остановить ответ':'Отправить сообщение'}" ${!state.busy&&actionsBlocked()?'disabled':''}>${icon(state.busy?'close':'send')}</button></form><div class="composer-foot"><span>Демо без списаний · Суммы показанных компонентов</span><button data-api-action="about">${icon('shield')}Как это работает</button></div></footer></main><aside class="sidebar ${drawer?'open':''}" aria-label="Параметры поездки">${sidebar()}</aside><button class="drawer-backdrop ${drawer?'open':''}" data-api-action="close-filters" aria-label="Закрыть параметры"></button></div>`;
  const newInput=root.querySelector('#api-chat-input');newInput.value=draft;if(focus){newInput.focus({preventScroll:true});if(selection)newInput.setSelectionRange(...selection);}
  const newArea=root.querySelector('.chat-scroll');newArea.scrollTop=nearBottom?newArea.scrollHeight:top;
 }
 function plan(index=null){if(!searchReady())return;const option=current().options.find(row=>row.index===index)||selected();if(!option)return;open('Проверьте состав поездки',parts(option),`<span class="demo-data-note">${esc(disclaimer)}</span>${current().stage==='awaiting_confirmation'&&current().selected===option.index?button('confirm','Подтверждаю состав',null,true):button('choose','Выбрать этот вариант',option.index,true)}`,true);}
 async function send(text){
  if(!text.trim()||current().busy)return;
  if(actionsBlocked()){toast('Сначала восстановите предыдущий ответ.');return;}
  close();const input=root.querySelector('#api-chat-input');if(input)input.value='';
  try{await controller.send(text);afterTurn();}
  catch(error){if(error?.name!=='AbortError')toast(error.message||'Связь прервалась. Можно повторить сообщение.');void controller.reconnect();}
 }
 async function retry(){
  if(current().busy)return;close();
  try{await controller.retry();afterTurn();}
  catch(error){if(error?.name!=='AbortError')toast(error.message||'Пока не удалось получить ответ. Переписка сохранена.');void controller.reconnect();}
 }
 function afterTurn(){if(actionsBlocked())return;if(current().stage==='awaiting_confirmation')plan(current().selected);else if(current().cart&&current().stage==='checkout_pending')checkout();}

 function editPreferences(){
  if(actionsBlocked())return;
  const state=current(),rail=isTrainTrip(state),assumed=tripAssumptions(searchReady()?state:{...state,options:[],assumptions:[]});
  const value=field=>state.brief[field]??assumed.find(row=>row.field===field)?.value??'';
  open('Изменить условия поиска',`<p class="about-text">Укажите нужные значения. Сервер заново подберёт варианты по этим условиям. Это не выбор варианта и не начало оформления.</p><form id="api-preferences-form" class="api-preferences-form" data-transport="${rail?'train':'flight'}"><label>Взрослые<input name="adults" type="number" min="1" max="12" step="1" value="${esc(value('adults'))}" required></label>${rail?'':`<label>Ночи<input name="nights" type="number" min="1" max="60" step="1" value="${esc(value('nights'))}" required></label>`}<label>${rail?'Дата отправления':'Дата вылета'}<input name="start_date" type="date" value="${isoDay(value('start_date'))||''}"><small>Пустое поле сохраняет текущие условия по датам.</small></label><p class="demo-data-note">Применяя форму, вы явно задаёте указанные в ней условия. Остальные пожелания сохраняются.</p><button class="primary-button" type="submit">Применить и пересчитать</button></form>`,'','preferences');
 }

 function checkout(){
  const state=current(),cart=state.cart;if(isTrainTrip(state)){toast('Оформление железнодорожных билетов не подключено.');return;}if(!searchReady()){toast('Сначала обновите подбор под текущие условия.');return;}if(actionsBlocked()){toast('Сначала восстановите ответ.');return;}if(!cart?.package){toast('Сначала выберите и подтвердите вариант поездки.');return;}
  const expected=cart.expected_travelers||{adults:state.brief.adults||1,children_ages:state.brief.children_ages||[]};
  const dayString=cart.package.outbound.departure_at.slice(0,10),year=Number(dayString.slice(0,4));
  const ages=[...Array.from({length:expected.adults},()=>35),...(expected.children_ages||[])];
  const fields=ages.map((age,index)=>{const born=age>=18?'1990-01-01':String(year-age)+'-01-01';return `<div class="checkout-grid"><label>Вымышленное имя · путешественник ${index+1}<input name="name-${index}" required maxlength="120" autocomplete="off" value="ДЕМО Путешественник ${index+1}"></label><label>Тестовая дата рождения<input name="birth-${index}" type="date" value="${born}" required></label></div>`;}).join('');
  open('Демонстрационное оформление',`<div class="demo-note">Используйте вымышленные данные. Банковская карта не нужна. ${esc(disclaimer)}</div>${parts(cart.package)}<form id="api-checkout-form" data-count="${ages.length}"><h3>Тестовые путешественники</h3>${fields}<label class="checkbox-label"><input name="ack-demo" type="checkbox" required><span>Понимаю, что оплата имитируется. Деньги не спишутся, билеты и брони не оформятся.</span></label><label class="checkbox-label"><input name="ack-extras" type="checkbox" required><span>Понимаю, что ${esc(extras(cart.package.unpriced_components))} не оценены и не входят в показанную сумму.</span></label><p id="api-payment-status" class="api-payment-status" role="status">${cart.status==='payment_declined'?'Тестовый отказ. Заказ не создан; можно повторить имитацию оплаты.':''}</p><div class="api-payment-buttons"><button class="secondary-button" type="submit" data-outcome="declined">Проверить отказ оплаты</button><button class="primary-button" type="submit" data-outcome="approved">${icon('lock')}Оплатить в демо</button></div></form>`,'',true);
 }
 function success(entry=null){const order=entry?.order||current().order;if(!order)return;const index=entry?current().orders.indexOf(entry):current().orders.findIndex(row=>row.order.order_id===order.order_id);open('Демо-заказ сохранён',`<div class="success-view"><div class="success-circle">${icon('check')}</div><h3>План поездки готов</h3><p>${esc(order.package.hotel.name)}<br>${day(order.package.hotel.check_in)} — ${day(order.package.hotel.check_out)}<br><b>${money(order.package.known_total_rub)}</b> по показанным компонентам</p><p>${esc(disclaimer)}</p></div><div class="booking-actions"><button class="primary-button" data-api-action="download-voucher" data-order-index="${index}">${icon('download')}Скачать демо-ваучер</button><button class="secondary-button" data-api-action="download-calendar" data-order-index="${index}">${icon('calendar')}Скачать календарь .ics</button></div><p class="demo-data-note">Обратный трансфер, визы и прочие обязательные доплаты не оценены.</p>`);}
 function orders(){open('Мои демо-поездки',current().orders.length?current().orders.map((entry,index)=>`<article class="plan-inline"><h3>${esc(entry.order.package.hotel.name)}</h3><p>${day(entry.order.package.hotel.check_in)} — ${day(entry.order.package.hotel.check_out)} · ${money(entry.order.package.known_total_rub)}</p><p class="demo-data-note">Оплата имитирована; поставщики услуги не бронировали.</p><button class="action-button primary" data-api-action="order" data-order-index="${index}">Открыть документы</button></article>`).join(''):'<p class="modal-empty">Сохранённых демо-заказов пока нет. Найдите поездку и завершите демонстрационное оформление.</p>');}
 async function download(kind,index){const entry=current().orders[index];try{const {blob,filename}=await controller.download(kind,entry);const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(kind==='voucher'?'Демо-ваучер скачан.':'Календарь скачан.');}catch(error){toast(error.message||'Документ пока недоступен.');}}
 function about(){open('Как устроена демонстрация',`<p class="about-text">Тревел-агент помогает подобрать перелёты, отель и трансфер, учесть даты, бюджет и пожелания, а затем собрать план поездки.</p><p class="about-text">Котировки Aviasales сохранены заранее. Сгенерированные рейсы отмечены «ДЕМО-МОК». Стоимость группы, багаж, отель и трансферы расчётные; наличие услуг не подтверждено.</p><p class="demo-note">${esc(disclaimer)}</p><p class="about-text">Изображения — авторские иллюстрации; отзывы — синтетические примеры. Названия и координаты отелей: © участники OpenStreetMap, ODbL; цены и правила услуг расчётные. <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">Источник и условия OpenStreetMap</a>. </p>`);}
 document.addEventListener('click',event=>{
  const target=event.target.closest('[data-api-action],[data-api-prompt]');if(!target||target.disabled)return;
  if(target.dataset.apiPrompt){send(target.dataset.apiPrompt);return;}
  const action=target.dataset.apiAction,index=Number(target.dataset.index);
  if(['choose','confirm','plan','profile','savings','compare'].includes(action)&&(!searchReady()||actionsBlocked()))return;
  if(action==='retry')retry();else if(action==='reconnect'){recoveryDelay=2000;void controller.reconnect();}else if(action==='restart-session'){controller.restartSession();void controller.reconnect();}else if(action==='close')close();else if(action==='stop')controller.abort?.abort();else if(action==='new'){close();controller.reset();}else if(action==='home')root.querySelector('.chat-scroll').scrollTo({top:0,behavior:'smooth'});
  else if(action==='expand-message'){const index=Number(target.dataset.messageIndex),details=Number.isInteger(index)&&root.querySelector('#api-full-answer-'+index);if(details){details.open=true;openDisclosures.add('message-'+index);details.querySelector('summary')?.focus();}}
  else if(action==='accept-assumptions'){if(!actionsBlocked())controller.acceptAssumptions();}else if(action==='edit-preferences')editPreferences();
  else if(action==='compare'){if(!current().options.some(option=>option.index===index))return;if(compared.has(index)){compared.delete(index);compareNotice='';}else if(compared.size<3){compared.add(index);compareNotice=compared.size<2?'Добавьте ещё один вариант для сравнения.':'';}else compareNotice='Можно сравнить до трёх вариантов. Уберите один, чтобы добавить другой.';render();}else if(action==='clear-comparison'){compared.clear();compareNotice='';render();}
  else if(action==='choose')send(`Беру вариант ${index}`);else if(action==='confirm')send('Подтверждаю');else if(action==='plan')plan(index);else if(action==='checkout')checkout();
  else if(action==='profile')send(`Почему вариант ${index} подходит? Что говорят отзывы?`);else if(action==='savings')send(`Для варианта ${current().selected||current().options[0]?.index||1}: если сдвинуть даты на 1–3 дня, можно сэкономить?`);
  else if(action==='success')success();else if(action==='orders')orders();else if(action==='order')success(current().orders[Number(target.dataset.orderIndex)]);
  else if(action==='download-voucher')download('voucher',Number(target.dataset.orderIndex));else if(action==='download-calendar')download('calendar',Number(target.dataset.orderIndex));
  else if(action==='filters'){root.querySelector('.sidebar').classList.add('open');root.querySelector('.drawer-backdrop').classList.add('open');}else if(action==='close-filters'){root.querySelector('.sidebar').classList.remove('open');root.querySelector('.drawer-backdrop').classList.remove('open');}
  else if(action==='about')about();else if(action==='prototype'){try{localStorage.setItem('na-maldivy-mode','demo');location.reload();}catch{toast('Не удалось переключить режим.');}}
 });
 document.addEventListener('submit',async event=>{
  if(event.target.id==='api-chat-form'){event.preventDefault();send(root.querySelector('#api-chat-input').value);}
  if(event.target.id==='api-preferences-form'){
   event.preventDefault();const form=event.target;if(actionsBlocked()||!form.reportValidity())return;
   const data=new FormData(form),rail=form.dataset?.transport==='train',adults=Number(data.get('adults')),nights=rail?null:Number(data.get('nights')),date=String(data.get('start_date')||'');
   if(!Number.isInteger(adults)||adults<1||adults>12||!rail&&(!Number.isInteger(nights)||nights<1||nights>60)||date&&!isoDay(date))return;
   send(`Изменить условия поиска: ${adultsLabel(adults)}${rail?'':', '+nightsLabel(nights)}${date?', дата '+(rail?'отправления':'вылета')+' '+day(date):''}. Заново подобрать варианты, без оформления.`);return;
  }
  if(event.target.id!=='api-checkout-form')return;
  event.preventDefault();const form=event.target;if(paymentBusy||!form.reportValidity())return;
  const data=new FormData(form),outcome=event.submitter?.dataset.outcome||'approved';
  const travelers=Array.from({length:Number(form.dataset.count)},(_,index)=>({full_name:String(data.get('name-'+index)||''),birth_date:String(data.get('birth-'+index)||'')}));
  paymentBusy=true;form.querySelectorAll('button').forEach(button=>button.disabled=true);
  try{const result=await controller.pay({travelers,outcome,acknowledgeDemo:data.get('ack-demo')==='on',acknowledgeUnpriced:data.get('ack-extras')==='on'});if(result?.status==='paid_demo')success();else{const status=form.querySelector('#api-payment-status');if(status)status.textContent='Тестовый отказ. Деньги не списаны, заказ не создан. Можно повторить имитацию оплаты.';}}
  catch(error){const status=form.querySelector('#api-payment-status');if(status)status.textContent=visibleText(error.message||'Оформление не завершено.');}
  finally{paymentBusy=false;if(form.isConnected)form.querySelectorAll('button').forEach(button=>button.disabled=false);}
 });
 document.addEventListener('keydown',event=>{if(event.target.id==='api-chat-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();send(event.target.value);}});
 modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)close();}});
 const onInput=event=>{if(event.target.id==='api-chat-input')controller.setDraft(event.target.value);};
 const onOnline=()=>{recoveryDelay=2000;void controller.reconnect();};
 const onOffline=()=>{controller.state.connection='offline';controller.notify();};
 const onVisible=()=>{if(document.visibilityState==='visible'&&(current().connection!=='online'||current().syncNeeded||current().pendingRequest))onOnline();};
 const onHide=()=>controller.remember();
 root.addEventListener('input',onInput);window.addEventListener('online',onOnline);window.addEventListener('offline',onOffline);document.addEventListener('visibilitychange',onVisible);window.addEventListener('pagehide',onHide);
 controller.dispose=()=>{disposed=true;clearTimeout(recoveryTimer);root.removeEventListener('input',onInput);window.removeEventListener('online',onOnline);window.removeEventListener('offline',onOffline);document.removeEventListener('visibilitychange',onVisible);window.removeEventListener('pagehide',onHide);controller.remember();};
 render();void controller.restore().then(()=>controller.reconnect());
 return controller;
}
